VOWELS = "aeiou"


def _translate_word(word):
    # Rule 1: begins with a vowel, or starts with "xr" or "yt".
    if word[0] in VOWELS or word[:2] in ("xr", "yt"):
        return word + "ay"

    # Otherwise the word begins with consonants. Find where the
    # consonant cluster ends: at the first vowel, at a "qu" (which is
    # moved along with the consonants), or at a "y" (treated as a vowel
    # once it is not the leading letter).
    i = 0
    while i < len(word):
        if word[i] in VOWELS:
            break
        if word[i:i + 2] == "qu":
            i += 2
            break
        if word[i] == "y" and i > 0:
            break
        i += 1

    return word[i:] + word[:i] + "ay"


def translate(text):
    return " ".join(_translate_word(word) for word in text.split(" "))
